import{_ as a,o as t,c as i,ai as r}from"./chunks/framework.Ci0kozOl.js";const u=JSON.parse('{"title":"Data Transfer","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/packages/data-transfer.md","filePath":"2.0/packages/data-transfer.md","lastUpdated":1786019473000}'),o={name:"2.0/packages/data-transfer.md"};function s(n,e,l,p,d,h){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="data-transfer" tabindex="-1">Data Transfer <a class="header-anchor" href="#data-transfer" aria-label="Permalink to &quot;Data Transfer&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Creating custom data import and export functionalities in UnoPim allows seamless bulk data management directly from the admin panel under the <code>Settings Menu</code>. This feature is essential for efficiently handling large datasets within your application.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>Import is a feature that allows users to import large quantities of data into a system quickly and efficiently. It simplifies the process and saves time by not having to add each piece of information one by one.</p><p>The feature works differently for each system and has a vast variety of use cases across many industries as well as <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Exporting data to save information in files is a common practice for data management, analysis, and sharing. This involves transferring data from a source system into a file format that is suitable for storage, future use, or sharing with others.</p><h2 id="import-export-tracker-ui-v2-0-0" tabindex="-1">Import/Export Tracker UI (v2.0.0) <a class="header-anchor" href="#import-export-tracker-ui-v2-0-0" aria-label="Permalink to &quot;Import/Export Tracker UI (v2.0.0)&quot;">​</a></h2><p>UnoPim v2.0.0 introduces a real-time <strong>Import/Export Tracker</strong> in the admin panel that provides step-by-step pipeline visualization for running jobs. The tracker displays each stage of the import or export process, including validation, processing, and indexing, with live progress indicators.</p><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>Real-time step pipeline visualization</strong> showing the current stage, completed stages, and remaining stages of the job.</li><li><strong>Job-specific logging</strong> that captures detailed logs for each import/export run, making it easier to diagnose issues.</li><li><strong>Pause, Resume, and Cancel controls</strong> available directly in the tracker UI, allowing administrators to manage running jobs without terminal access.</li></ul><h2 id="file-upload-enhancements-v2-0-0" tabindex="-1">File Upload Enhancements (v2.0.0) <a class="header-anchor" href="#file-upload-enhancements-v2-0-0" aria-label="Permalink to &quot;File Upload Enhancements (v2.0.0)&quot;">​</a></h2><h3 id="drag-and-drop-file-upload" tabindex="-1">Drag-and-Drop File Upload <a class="header-anchor" href="#drag-and-drop-file-upload" aria-label="Permalink to &quot;Drag-and-Drop File Upload&quot;">​</a></h3><p>Import jobs now support <strong>drag-and-drop file upload</strong> for CSV, XLSX, and XLS files. Users can drag files directly onto the import configuration form instead of using the traditional file picker.</p><h3 id="zip-image-upload-modal" tabindex="-1">ZIP Image Upload Modal <a class="header-anchor" href="#zip-image-upload-modal" aria-label="Permalink to &quot;ZIP Image Upload Modal&quot;">​</a></h3><p>A dedicated <strong>ZIP image upload modal</strong> with drag-and-drop support is available for importing product images in bulk. Users can upload a ZIP archive containing product images, which are automatically extracted and associated with the corresponding products.</p><h2 id="optimized-export-pipeline-v2-0-0" tabindex="-1">Optimized Export Pipeline (v2.0.0) <a class="header-anchor" href="#optimized-export-pipeline-v2-0-0" aria-label="Permalink to &quot;Optimized Export Pipeline (v2.0.0)&quot;">​</a></h2><p>The export pipeline has been significantly optimized for better performance with large datasets:</p><ul><li><strong>Eager loading</strong> of relationships to reduce N+1 query issues during export.</li><li><strong>Cached <code>initialize()</code> method</strong> to avoid redundant setup on each batch iteration.</li><li><strong>Increased <code>BATCH_SIZE</code> to 200</strong> for faster throughput on large catalogs.</li><li><strong>Optimized category export</strong> that replaces in-memory product loading with direct count queries, preventing timeouts on large catalogs with millions of products.</li></ul><h3 id="export-batch-job-reliability" tabindex="-1">Export Batch Job Reliability <a class="header-anchor" href="#export-batch-job-reliability" aria-label="Permalink to &quot;Export Batch Job Reliability&quot;">​</a></h3><p>Export batch jobs now support <code>$tries</code> and <code>$timeout</code> properties for improved queue reliability. These allow you to configure retry attempts and timeout duration per job:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Example configuration on an export batch job</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">protected</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $tries   </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Retry up to 3 times on failure</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">protected</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $timeout </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1800</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 30-minute timeout per attempt</span></span></code></pre></div><p>Tuning these values helps prevent silent failures on long-running exports and ensures jobs are retried automatically when transient errors occur.</p><h2 id="optimized-import-pipeline-v2-0-0" tabindex="-1">Optimized Import Pipeline (v2.0.0) <a class="header-anchor" href="#optimized-import-pipeline-v2-0-0" aria-label="Permalink to &quot;Optimized Import Pipeline (v2.0.0)&quot;">​</a></h2><p>The import pipeline includes several performance and reliability improvements:</p><ul><li><strong>Deferred indexing</strong> that postpones search index updates until after the entire import completes, reducing overhead during processing.</li><li><strong>Field processor improvements</strong> for faster attribute value parsing and validation.</li><li><strong>Batch state tracking</strong> that persists progress per batch, enabling accurate resume after pause or failure.</li><li><strong>Configurable batch and chunk sizes</strong> allowing administrators to tune import performance based on server resources and dataset characteristics.</li></ul><h2 id="translatable-tracker-ui-v2-0-0" tabindex="-1">Translatable Tracker UI (v2.0.0) <a class="header-anchor" href="#translatable-tracker-ui-v2-0-0" aria-label="Permalink to &quot;Translatable Tracker UI (v2.0.0)&quot;">​</a></h2><p>All tracker UI elements now use <strong>translation strings</strong> instead of hardcoded text. Labels such as &quot;Importing&quot;, &quot;Exporting&quot;, step names, and status messages are fully translatable, making it straightforward to localize the entire import/export experience.</p><ul><li>Labels, button text, and progress messages are resolved through Laravel&#39;s translation helpers (<code>trans()</code> / <code>__()</code>).</li><li>Custom tracker labels can be overridden by publishing or editing the corresponding language files in your package&#39;s <code>Resources/lang/{locale}/</code> directory.</li></ul>`,30)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
